using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Ordella_deliverable2.Data;using Ordella_deliverable2.Models;
namespace Ordella_deliverable2.Controllers;
[Authorize(Roles="Seller")] public class DashboardController:Controller
{private readonly ApplicationDbContext db;private readonly UserManager<IdentityUser> users;public DashboardController(ApplicationDbContext d,UserManager<IdentityUser>u){db=d;users=u;}private string Owner=>users.GetUserId(User)!;
 public async Task<IActionResult> Index(){ViewBag.Shop=await db.Shops.FirstOrDefaultAsync(s=>s.OwnerId==Owner);ViewBag.Orders=await db.Orders.Where(o=>o.Shop!=null&&o.Shop.OwnerId==Owner).OrderByDescending(o=>o.CreatedAt).Take(8).ToListAsync();return View();}
 [HttpGet] public async Task<IActionResult> Shop(){var s=await db.Shops.FirstOrDefaultAsync(x=>x.OwnerId==Owner);return View(s??new Shop());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Shop(Shop model){if(!ModelState.IsValid)return View(model);var existing=await db.Shops.FirstOrDefaultAsync(x=>x.OwnerId==Owner);var slug=Slugify(model.Name);if(await db.Shops.AnyAsync(x=>x.Slug==slug&&x.Id!=(existing?.Id??0))){ModelState.AddModelError("Name","A shop with a similar link already exists. Change the shop name.");return View(model);}if(existing==null){model.OwnerId=Owner;model.Slug=slug;db.Shops.Add(model);}else{existing.Name=model.Name;existing.Description=model.Description;existing.ContactEmail=model.ContactEmail;existing.BannerUrl=model.BannerUrl;existing.Slug=slug;}await db.SaveChangesAsync();TempData["Message"]="Shop profile saved.";return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Products(){var shop=await db.Shops.FirstOrDefaultAsync(s=>s.OwnerId==Owner);if(shop==null)return RedirectToAction(nameof(Shop));return View(await db.Products.Where(p=>p.ShopId==shop.Id).ToListAsync());}
 [HttpGet] public async Task<IActionResult> AddProduct(){if(!await db.Shops.AnyAsync(s=>s.OwnerId==Owner))return RedirectToAction(nameof(Shop));return View(new Product());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> AddProduct(Product model){var shop=await db.Shops.FirstOrDefaultAsync(s=>s.OwnerId==Owner);if(shop==null)return RedirectToAction(nameof(Shop));if(!ModelState.IsValid)return View(model);model.ShopId=shop.Id;db.Products.Add(model);await db.SaveChangesAsync();return RedirectToAction(nameof(Products));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> TogglePublish(){var s=await db.Shops.FirstOrDefaultAsync(x=>x.OwnerId==Owner);if(s==null)return RedirectToAction(nameof(Shop));s.IsPublished=!s.IsPublished;await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> DeleteProduct(int id){var p=await db.Products.Include(x=>x.Shop).FirstOrDefaultAsync(x=>x.Id==id&&x.Shop!.OwnerId==Owner);if(p!=null){db.Products.Remove(p);await db.SaveChangesAsync();}return RedirectToAction(nameof(Products));}
 public async Task<IActionResult> Orders(){return View(await db.Orders.Include(o=>o.Items).Include(o=>o.Shop).Where(o=>o.Shop!.OwnerId==Owner).OrderByDescending(o=>o.CreatedAt).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> UpdateStatus(int id,string status){var allowed=new[]{"Received","Confirmed","In Progress","Ready","Completed","Cancelled"};var o=await db.Orders.Include(x=>x.Shop).FirstOrDefaultAsync(x=>x.Id==id&&x.Shop!.OwnerId==Owner);if(o!=null&&allowed.Contains(status)){o.Status=status;await db.SaveChangesAsync();}return RedirectToAction(nameof(Orders));}
 private static string Slugify(string s)=>System.Text.RegularExpressions.Regex.Replace(s.Trim().ToLowerInvariant(),"[^a-z0-9]+","-").Trim('-');
}
